export interface TournamentResult {
  /** 對應 tier-list.ts 裡的 deck slug；官方尚未公開卡表、無法確認牌組時留 null。 */
  deckSlug: string | null;
  date: string; // ISO, e.g. "2026-05-09"
  tournamentNameZh: string;
  tournamentNameEn: string;
  region: string; // 中文地區名稱，例如「美國・洛杉磯」
  player: string; // 選手名字維持原文，不翻譯；來源沒寫選手名字時填「無」
  placement: number | null; // 29 → 顯示為「第 29 名」；來源沒有名次資訊時為 null，顯示「無」
  /** 官方賽事頁面連結，可查詢最新戰績。 */
  standingsUrl: string;
  /** 若官方有公開完整卡表圖片／頁面，放連結；沒有則為 null。 */
  decklistUrl: string | null;
}

// 資料來源：Limitless TCG（https://limitlesstcg.com/tournaments），彙整範圍為
// 「福岡冠軍聯賽」（2026-02-21）到目前為止最新一場賽事（2026-06-10 NAIC 紐奧良），
// 只收錄各賽事「32 強」以內、且牌組能對應到 tier-list.ts 現有牌組的戰績。
// 部分歷史賽事的牌組尚未套用「超級進化ex」機制（例如當時是單純的多龍、路卡利歐、
// 妙蛙花等），已依核心寶可夢歸類到對應的現行牌組。
// 之後新增資料時，照同樣的欄位格式加進陣列即可，頁面會自動依日期新→舊、
// 同日期依名次排序。
